// Original October art, exported from the Figma art kit
// (https://www.figma.com/design/jk7Iwd2BLfkYyYmSHPWCmm, page "04 · Art kit").
// The Figma components are the master copies; these strings are generated
// from them with layer names stripped. All shapes are original drawings —
// nothing is traced from Disney's 1949 film or the 1999 film.
//
// Kept as SVG strings so the TV can paint them onto one canvas as images
// (cheap with 40+ pumpkins) and phones can show them as <img>s. As images
// their gradient ids never collide, however many copies are on screen.

export interface OctoberArt {
  svg: string;
  width: number;
  height: number;
}

